227	function rotateUv([u1, v1, u2, v2], rot) {
228	  rot = ((rot % 360) + 360) % 360;
229	  if (rot === 90) return [u2, v1, u2, v2, u1, v2, u1, v1];
230	  if (rot === 180) return [u2, v2, u1, v2, u1, v1, u2, v1];
231	  if (rot === 270) return [u1, v2, u1, v1, u2, v1, u2, v2];
232	  return [u1, v1, u1, v2, u2, v2, u2, v1];
233	}
