292	  const buf = Buffer.alloc(24);
293	  await fd.read(buf, 0, 24, 0);
294	  await fd.close();
295	  if (buf.readUInt32BE(0) !== 0x89504e47) throw new Error('not a png: ' + file);
296	  return { w: buf.readUInt32BE(16), h: buf.readUInt32BE(20) };
