432	    if (existsSync(metaSrc)) await fs.copyFile(metaSrc, path.join(OUT, outRel + '.mcmeta'));
433	    const arrayable = size.w === 16 && size.h === 16 * frames;
434	    const framePaths = [];
435	    if (arrayable && anim && frames > 1) {
436	      const full = PNG.sync.read(await fs.readFile(info.src));
437	      for (let f = 0; f < frames; f++) {
438	        const frame = new PNG({ width: 16, height: 16 });
439	        for (let y = 0; y < 16; y++) {
440	          const srcStart = ((f * 16 + y) * full.width) * 4;
441	          const dstStart = (y * 16) * 4;
442	          full.data.copy(frame.data, dstStart, srcStart, srcStart + 16 * 4);
443	        }
444	        const frameRel = path.posix.join('textures', `${key}.${f}.png`);
445	        await fs.writeFile(path.join(OUT, frameRel), PNG.sync.write(frame));
446	        framePaths.push('/' + path.posix.join(path.basename(OUT), frameRel));
447	      }
448	    } else {
