472	  // Environment, GUI, font, misc, colormap, particles.
473	  await copyTree(path.join(SRC, 'textures/gui'), path.join(OUT, 'gui'));
474	  await copyTree(path.join(SRC, 'textures/environment'), path.join(OUT, 'environment'));
475	  await copyTree(path.join(SRC, 'textures/misc'), path.join(OUT, 'misc'));
