1	import { loadAssets } from './assets.js';
2	import { BlockRegistry } from './blocks.js';
3	import { World } from './world.js';
4	import { Renderer } from './renderer.js';
5	import { Player } from './player.js';
6	import { Hud } from './hud.js';
7	import { GameAudio } from './audio.js';
8	
9	async function boot(): Promise<void> {
10	  const gameCanvas = document.getElementById('game') as HTMLCanvasElement;
11	  const uiCanvas = document.getElementById('ui') as HTMLCanvasElement;
12	  const loading = document.getElementById('loading')!;
13	  const label = document.getElementById('loading-label')!;
14	  const bar = document.getElementById('loading-bar')!;
15	
16	  const setProgress = (f: number, text: string) => {
17	    bar.style.width = `${Math.round(Math.min(1, Math.max(0, f)) * 100)}%`;
18	    label.textContent = text;
19	  };
20	
21	  const gl = gameCanvas.getContext('webgl2', {
22	    alpha: false,
23	    antialias: true,
24	    depth: true,
25	    powerPreference: 'high-performance',
26	    preserveDrawingBuffer: false,
27	  });
28	  if (!gl) {
29	    label.textContent = 'WebGL2 is not available in this browser.';
30	    return;
31	  }
32	  gl.clearColor(0.47, 0.65, 1, 1);
33	
34	  const params = new URLSearchParams(location.search);
35	  const preview = params.has('preview');
36	  const t0 = performance.now();
37	  try {
38	    setProgress(0.01, 'Loading official 26.2 resources');
39	    const assets = await loadAssets(gl, setProgress);
40	    const tAssets = performance.now();
41	    const rocks = new BlockRegistry(assets.manifest);
42	    const audio = new GameAudio(assets.manifest.audio?.events ?? {});
43	    setProgress(0.71, 'Preparing world');
44	    const world = new World(rocks, assets, 0x2602c0de);
45	    await world.generate(setProgress);
46	    const spawn = world.findSpawn();
47	    world.decorateSpawn(spawn);
48	    const tWorld = performance.now();
49	    const renderer = new Renderer(gl, assets, rocks);
50	    let mipmapMode = 0;
51	    renderer.setTextureFilter(mipmapMode);
52	    await renderer.buildAll(world, setProgress);
53	    const tMesh = performance.now();
54	    console.log(`[timing] assets ${(tAssets - t0).toFixed(0)}ms world ${(tWorld - tAssets).toFixed(0)}ms mesh ${(tMesh - tWorld).toFixed(0)}ms total ${(tMesh - t0).toFixed(0)}ms`);
55	    const player = new Player(world, rocks, spawn);
56	    player.yaw = Number(params.get('yaw') ?? spawn.yaw ?? world.suggestYaw(spawn.x, spawn.z));
57	    player.pitch = Number(params.get('pitch') ?? 0.12);
58	    player.attach(gameCanvas);
59	    const knownSounds = new Set(['stone', 'grass', 'wood', 'sand', 'gravel', 'glass', 'snow', 'wool']);
60	    const soundFor = (id: number): string => {
61	      const s = rocks.get(id).flags?.sound ?? 'stone';
62	      return knownSounds.has(s) ? s : (s === 'lantern' ? 'glass' : 'stone');
63	    };
64	    player.setBlockChangeHandler((x, y, z, oldId, newId) => {
65	      if (oldId) audio.play(`block.${soundFor(oldId)}.break`, 0.65);
66	      if (newId) audio.play(`block.${soundFor(newId)}.place`, 0.6);
67	      world.relightAround(x, y, z, 20);
68	      renderer.invalidateArea(x >> 4, z >> 4, world, 1);
69	    });
70	
71	    const hud = new Hud(uiCanvas, assets, rocks, world);
72	    let started = preview;
73	    let inventoryOpen = false;
74	    let debug = false;
75	    let timeFrozen = false;
76	    let ticks = 1000;
77	    let elapsed = 0;
78	    let fps = 60;
79	    let last = performance.now();
80	    let underwater = false;
81	    let stepTimer = 0;
82	
83	    const resize = () => {
84	      const dpr = Math.min(window.devicePixelRatio || 1, 1.5);
85	      const w = Math.max(1, Math.floor(window.innerWidth * dpr));
86	      const h = Math.max(1, Math.floor(window.innerHeight * dpr));
87	      if (gameCanvas.width !== w || gameCanvas.height !== h) {
88	        gameCanvas.width = w;
89	        gameCanvas.height = h;
90	        gameCanvas.style.width = window.innerWidth + 'px';
91	        gameCanvas.style.height = window.innerHeight + 'px';
92	        renderer.setViewport(w, h);
93	      }
94	      hud.resize(window.innerWidth, window.innerHeight);
95	    };
96	    window.addEventListener('resize', resize);
97	    resize();
98	
99	    const openInventory = () => {
100	      if (!started || inventoryOpen) return;
101	      inventoryOpen = true;
102	      hud.setInventory(true);
103	      hud.setMouse(window.innerWidth / 2, window.innerHeight / 2);
104	      audio.play('ui.button.click', 0.25);
105	      if (document.pointerLockElement === gameCanvas) document.exitPointerLock();
106	    };
107	    const closeInventory = () => {
108	      if (!inventoryOpen) return;
109	      inventoryOpen = false;
110	      hud.setInventory(false);
111	      audio.play('ui.button.click', 0.25);
112	      player.requestLock();
113	    };
114	
115	    gameCanvas.addEventListener('click', (e) => {
116	      if (inventoryOpen) {
117	        const hit = hud.inventoryHit(e.clientX, e.clientY);
118	        if (!hit) return;
119	        void audio.init();
120	        audio.play('ui.button.click', 0.25);
121	        if ('page' in hit) {
122	          const totalBlocks = rocks.blocks.length - 1;
123	          const pages = Math.max(1, Math.ceil(totalBlocks / 45));
124	          hud.inventoryPage = Math.max(0, Math.min(pages - 1, hud.inventoryPage + hit.page));
125	          return;
126	        }
127	        const def = rocks.get(hit.block);
128	        const existing = player.hotbar.findIndex(b => b.id === def.id);
129	        if (existing >= 0) player.selected = existing;
130	        else player.hotbar[player.selected] = def;
131	        player.selectedSince = performance.now();
132	        closeInventory();
133	        return;
134	      }
135	      void audio.init();
136	      audio.play('ui.button.click', 0.3);
137	      if (document.pointerLockElement !== gameCanvas) player.requestLock();
138	    });
139	    document.addEventListener('mousemove', (e) => {
140	      if (inventoryOpen) hud.setMouse(e.clientX, e.clientY);
141	    });
142	    document.addEventListener('pointerlockchange', () => {
143	      if (document.pointerLockElement === gameCanvas) started = true;
144	    });
145	
146	    document.addEventListener('keydown', (e) => {
147	      if (inventoryOpen) {
148	        if (e.code === 'KeyE' || e.code === 'Escape') {
149	          e.preventDefault();
150	          closeInventory();
151	        } else if (e.code === 'ArrowLeft') {
152	          hud.inventoryPage = Math.max(0, hud.inventoryPage - 1);
153	        } else if (e.code === 'ArrowRight') {
154	          const pages = Math.max(1, Math.ceil((rocks.blocks.length - 1) / 45));
155	          hud.inventoryPage = Math.min(pages - 1, hud.inventoryPage + 1);
156	        }
157	        return;
158	      }
159	      if (!player.locked) return;
160	      if (e.code === 'KeyE') {
161	        e.preventDefault();
162	        openInventory();
163	      } else if (e.code === 'F3') {
164	        e.preventDefault();
165	        debug = !debug;
166	      } else if (e.code === 'KeyN') {
167	        ticks = 6000;
168	      } else if (e.code === 'KeyM') {
169	        ticks = 18000;
170	      } else if (e.code === 'KeyT' && !e.repeat) {
171	        timeFrozen = !timeFrozen;
172	      } else if (e.code === 'KeyV' && !e.repeat) {
173	        mipmapMode = (mipmapMode + 1) % 4;
174	        renderer.setTextureFilter(mipmapMode);
175	        hud.toast(['Mipmap: Off (pixel)', 'Mipmap: Nearest', 'Mipmap: Linear blend', 'Mipmap: Smooth'][mipmapMode]);
176	      }
177	    });
178	
179	    loading.classList.add('hidden');
180	    document.body.classList.add('ready');
181	    (window as any).__mc = {
182	      player, world, renderer, hud,
183	      getTicks: () => ticks,
184	      setTicks: (v: number) => { ticks = v; },
185	      setDebug: (v: boolean) => { debug = v; },
186	      setTimeFrozen: (v: boolean) => { timeFrozen = v; },
187	      audio, getUnderwater: () => underwater, setTextureFilter: (m: number) => { mipmapMode = m; renderer.setTextureFilter(m); },
188	      openInventory, closeInventory, isInventoryOpen: () => inventoryOpen,
189	      preview,
190	    };
191	    window.addEventListener('contextmenu', e => e.preventDefault());
192	
193	    const loop = (now: number) => {
194	      const dt = Math.min(0.1, Math.max(0, (now - last) / 1000));
195	      last = now;
196	      elapsed += dt;
197	      if (dt > 0) fps = fps * 0.9 + (1 / dt) * 0.1;
198	      if (started && player.locked) {
199	        player.update(dt);
200	        if (!timeFrozen) ticks += dt * 20;
201	        const horiz = Math.hypot(player.vel.x, player.vel.z);
202	        if (player.onGround && horiz > 0.7) {
203	          stepTimer -= dt;
204	          if (stepTimer <= 0) {
205	            const under = world.getBlock(Math.floor(player.pos.x), Math.floor(player.pos.y - 0.1), Math.floor(player.pos.z));
206	            const snd = soundFor(under);
207	            if (under) audio.play(`block.${snd}.step`, 0.32, 1);
208	            stepTimer = horiz > 5 ? 0.29 : 0.38;
209	          }
210	        } else {
211	          stepTimer = 0.05;
212	        }
213	      }
214	      const eye = player.eye();
215	      const eyeId = world.getBlock(Math.floor(eye.x), Math.floor(eye.y), Math.floor(eye.z));
216	      const wasUnderwater = underwater;
217	      underwater = eyeId !== 0 && rocks.byName.get('water')?.id === eyeId;
218	      if (underwater !== wasUnderwater && started) {
219	        audio.play(underwater ? 'ambient.underwater.enter' : 'ambient.underwater.exit', 0.45);
220	      }
221	      renderer.render(world, eye.x, eye.y, eye.z, player.yaw, player.pitch,
222	        player.locked ? player.target : null, ticks, elapsed, 6);
223	      hud.render({
224	        started,
225	        paused: started && !player.locked && !preview && !inventoryOpen,
226	        player,
227	        fps,
228	        ticks,
229	        debug,
230	        underwater,
